  `suggested_pooja` varchar(255) DEFAULT NULL,
  `astrological_remedies` text DEFAULT NULL,
  `social_remedies` text DEFAULT NULL,
  `emotional_remedies` text DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`remedy_id`),
  KEY `idx_af_remedies_lookup` (`sun_sign`,`gender`,`issue`,`language`)
) ENGINE=InnoDB AUTO_INCREMENT=1041 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

